SELECT target_issue FROM (SELECT target_issue FROM (SELECT p.target_issue FROM research_fixed_pair_r932 p JOIN research_fixed_window_r932 w ON w.window_id=p.window_id JOIN research_fixed_champion_r932 c ON c.target_issue=p.target_issue AND c.bundle_hash=w.champion_hash AND c.prediction_hash=p.champion_prediction_hash WHERE p.candidate_hit=-1 AND (EXISTS(SELECT 1 FROM draws d WHERE d.issue=p.target_issue AND d.dirty=0) OR (NOT EXISTS(SELECT 1 FROM draws d WHERE d.issue=p.target_issue) AND EXISTS(SELECT 1 FROM draw_dependency_input_cp12 d WHERE d.issue=p.target_issue AND d.dirty=0))) ORDER BY p.target_issue LIMIT 1) UNION SELECT target_issue FROM (SELECT p.target_issue FROM research_candidate_cal_observation_r932 p WHERE p.hit=-1 AND (EXISTS(SELECT 1 FROM draws d WHERE d.issue=p.target_issue AND d.dirty=0) OR (NOT EXISTS(SELECT 1 FROM draws d WHERE d.issue=p.target_issue) AND EXISTS(SELECT 1 FROM draw_dependency_input_cp12 d WHERE d.issue=p.target_issue AND d.dirty=0))) ORDER BY p.target_issue LIMIT 1)) pending ORDER BY target_issue LIMIT 1
